function paste(x=0,y=0,parentId?:string,slotId?:string){const clipboard=designerClipboard.value;if(clipboard?.type!=='widgets'||clipboard.projectId!==props.editor.project.value.id)return;const roots=clipboard.widgets.filter(widget=>!widget.parentId||!clipboard.widgets.some(parent=>parent.id===widget.parentId)),left=Math.min(...roots.map(widget=>widget.x)),top=Math.min(...roots.map(widget=>widget.y)),copies=props.editor.cloneWidgets(clipboard.widgets,{x:x-left,y:y-top},parentId??'');for(const widget of copies)if(!widget.parentId||widget.parentId===parentId)widget.slotId=slotId;if(props.editor.mutate(()=>props.editor.page.value.widgets.push(...copies)))props.editor.selected.value=copies.filter(widget=>!widget.parentId||!copies.some(parent=>parent.id===widget.parentId)).map(widget=>widget.id)}
