 if(id){items.push({label:'剪切',shortcut:'⌘/Ctrl X',disabled:!editable,action:()=>copy(true)},{label:'复制',shortcut:'⌘/Ctrl C',action:()=>copy()},{label:'复制副本',shortcut:'⌘/Ctrl D',action:props.editor.duplicateSelected},{label:'重命名',action:()=>{void nextTick(()=>document.querySelector<HTMLInputElement>('.inspector .property-section input')?.focus())}},{label:'删除',shortcut:'Delete',disabled:!editable,action:props.editor.removeSelected},{label:'',separator:true},{label:widget?.editor?.locked?'解锁':'锁定',action:()=>{const locked=!widget?.editor?.locked;props.editor.mutate(()=>{for(const target of selected)target.editor={...target.editor,locked}})}},{label:'隐藏',action:()=>props.editor.mutate(()=>{for(const target of selected)target.editor={...target.editor,hidden:true}})},{label:'置于顶层',action:()=>props.editor.mutate(()=>{const z=Math.max(...props.editor.page.value.widgets.map(widget=>widget.zIndex));selected.forEach((widget,index)=>widget.zIndex=z+index+1)})},{label:'置于底层',action:()=>props.editor.mutate(()=>{const z=Math.min(...props.editor.page.value.widgets.map(widget=>widget.zIndex));selected.forEach((widget,index)=>widget.zIndex=z-index-1)})});if(selected.length>1)items.push({label:'对齐',items:([['left','左对齐'],['right','右对齐'],['center','水平居中'],['top','顶端对齐'],['bottom','底端对齐'],['middle','垂直居中'],['horizontal','水平等距'],['vertical','垂直等距'],['width','等宽'],['height','等高']]as const).map(([direction,label])=>({label,action:()=>props.editor.align(direction)}))});const action=Object.values(widget?.events??{})[0];if(action)items.push({label:'编辑事件逻辑',action:()=>emit('logic',action.flowId,action.entryNodeId)})}
 if(!id||widget&&isContainer(widget)){const parent=id&&isContainer(widget!)?widget:undefined,element=parent?board.value?.querySelector<HTMLElement>(`[data-container-content="${parent.id}"]`):undefined,rect=element?.getBoundingClientRect(),local=rect?{x:(event.clientX-rect.left)/zoom.value,y:(event.clientY-rect.top)/zoom.value}:point;items.push({label:'添加组件',items:widgetKinds.map(spec=>({label:spec.label,action:()=>props.editor.addWidget(spec.kind,Math.round(local.x),Math.round(local.y),parent?.id,element?.dataset.slotId)}))},{label:'在此粘贴',disabled:!canPaste,action:()=>paste(local.x,local.y,parent?.id,element?.dataset.slotId)},{label:'布局',items:([['absolute','解除布局'],['horizontal','水平布局'],['vertical','垂直布局'],['grid','网格布局'],['form','表单布局']]as const).map(([type,label])=>({label,action:()=>setLayout(type,parent?.id)}))})}
 items.push({label:'',separator:true},{label:'全选',shortcut:'⌘/Ctrl A',action:()=>props.editor.selected.value=props.editor.page.value.widgets.filter(widget=>!widget.editor?.hidden).map(widget=>widget.id)},{label:'适应画布',action:fit},{label:'实际大小',action:()=>setZoom(1)},{label:'网格吸附',checked:grid.value,action:()=>grid.value=!grid.value},{label:'辅助线',checked:showGuides.value,action:()=>showGuides.value=!showGuides.value},{label:'标尺',checked:rulers.value,action:()=>rulers.value=!rulers.value},{label:'清除辅助线',disabled:!guides.value.length,action:()=>props.editor.mutate(()=>props.editor.page.value.guides=[])})
