}
function guideStart(event:PointerEvent,orientation:'horizontal'|'vertical',id?:string){event.preventDefault();cancelGuide?.();const axis=orientation==='horizontal'?'y':'x';let last={x:0,y:0};const move=(next:PointerEvent)=>{last=pagePoint(next.clientX,next.clientY);draftGuide.value={id:id??'draft',axis,position:Math.round(axis==='y'?last.y:last.x)}};move(event);const cleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);draftGuide.value=undefined;cancelGuide=undefined};const end=()=>{const value=draftGuide.value?.position??0,valid=last.x>=0&&last.y>=0&&last.x<=props.editor.project.value.width&&last.y<=props.editor.project.value.height;cleanup();if(!valid&&!id)return;props.editor.mutate(()=>{props.editor.page.value.guides??=[];const existing=props.editor.page.value.guides.find(guide=>guide.id===id);if(!valid){props.editor.page.value.guides=props.editor.page.value.guides.filter(guide=>guide.id!==id)}else if(existing)existing.position=value;else props.editor.page.value.guides.push({id:newId('guide'),axis,position:value})})};cancelGuide=cleanup;window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true})}
